components.calculateValue:
const opnieuwTeStartenTaken = [
    {
        label: 'Opnieuw informatieverzoek uitzetten',
        gebeurtenis: 'start-overwegen-uitzetten-informatieverzoek',
        actieUitzettenInformatieverzoek: 'opnieuw-uitzetten-informatieverzoek'
    },
    {
        label: 'Opnieuw overwegen inzetten handhaving',
        gebeurtenis: 'start-overwegen-inzetten-handhaving',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen leef en woonsituatie',
        gebeurtenis: 'start-vaststelling-leef-en-woonsituatie',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen verblijfadres aanvrager',
        gebeurtenis: 'start-vaststelling-verblijfadres',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen verblijfadres partner',
        gebeurtenis: 'start-vaststelling-verblijfadres-partner',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen verblijfstitel aanvrager',
        gebeurtenis: 'start-vaststelling-verblijfstitel',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen verblijfstitel partner',
        gebeurtenis: 'start-vaststelling-verblijfstitel-partner',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen ingangsdatum',
        gebeurtenis: 'start-vaststelling-ingangsdatum',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen relaties',
        gebeurtenis: 'start-vaststelling-relaties',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen norm',
        gebeurtenis: 'start-vaststelling-norm',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen vermogen',
        gebeurtenis: 'start-vaststelling-vermogen',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen inkomen aanvrager',
        gebeurtenis: 'start-vaststelling-inkomen-aanvrager',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen inkomen partner',
        gebeurtenis: 'start-vaststelling-inkomen-partner',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen voorliggende voorzieningen aanvrager',
        gebeurtenis: 'start-vaststelling-voorliggende-voorzieningen-aanvrager',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen voorliggende voorzieningen partner',
        gebeurtenis: 'start-vaststelling-voorliggende-voorzieningen-partner',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen uitsluitingsgronden aanvrager',
        gebeurtenis: 'start-vaststelling-uitsluitingsgronden-aanvrager',
        handmatigVaststellen: true
    },
    {
        label: 'Opnieuw vaststellen uitsluitingsgronden partner',
        gebeurtenis: 'start-vaststelling-uitsluitingsgronden-partner',
        handmatigVaststellen: true
    }
];

const status = data.openzaak?.statusOmschrijving;
const partnerAanwezig = !!data.gegevensVaststelling?.partner?.bsn;
const dossiertype = data.dossiertype;

const removeRules = [
    {
        gebeurtenis: 'start-overwegen-uitzetten-informatieverzoek',
        show: () => status !== 'Informatieverzoek uitgezet'
    },
    { gebeurtenis: 'start-vaststelling-leef-en-woonsituatie', },
    { gebeurtenis: 'start-vaststelling-verblijfadres' },
    {
        gebeurtenis: 'start-vaststelling-verblijfadres-partner',
        show: () => partnerAanwezig
    },
    { gebeurtenis: 'start-vaststelling-verblijfstitel' },
    {
        gebeurtenis: 'start-vaststelling-verblijfstitel-partner',
        show: () => partnerAanwezig
    },
    { gebeurtenis: 'start-vaststelling-ingangsdatum' },
    {
        gebeurtenis: 'start-vaststelling-vermogen',
        show: () => dossiertype === 'aanvraag-algemene-bijstand-dcm'
    },
    {
        gebeurtenis: 'start-vaststelling-inkomen-aanvrager',
        show: () => dossiertype === 'aanvraag-algemene-bijstand-dcm'
    },
    {
        gebeurtenis: 'start-vaststelling-inkomen-partner',
        show: () => dossiertype === 'aanvraag-algemene-bijstand-dcm' && partnerAanwezig
    },
    {
        gebeurtenis: 'start-vaststelling-voorliggende-voorzieningen-partner',
        show: () => partnerAanwezig
    },
    {
        gebeurtenis: 'start-vaststelling-uitsluitingsgronden-partner',
        show: () => partnerAanwezig
    }
];

const tasks = opnieuwTeStartenTaken.filter(task => {
    const rule = removeRules.find(rule => rule.gebeurtenis === task.gebeurtenis);
    if (rule?.show) {
        return rule.show();
    }
    return true;
});

value = tasks;
